"use client";

import React, { useEffect, useRef } from "react";
import gsap from "gsap";

export default function AuraStackCards({ slidesData }) {
  const containerRef = useRef(null);
  const cardsRef = useRef([]);

  // Store animation variables in a Ref to allow mutation without re-renders
  const state = useRef({
    target: 0,
    current: 0,
    isDragging: false,
    startX: 0,
    touchStart: 0,
    maxScroll: 0,

    // Responsive Dimensions (Calculated on init/resize)
    cardWidth: 400,
    gap: 40,
    viewWidth: 0,
  });

  useEffect(() => {
    // --- 1. RESPONSIVE SIZING LOGIC ---
    const calculateDimensions = () => {
      const isMobile = window.innerWidth < 768;

      // Mobile: Card takes 85% of screen width
      // Desktop: Fixed 400px
      state.current.cardWidth = isMobile ? window.innerWidth * 0.85 : 400;
      state.current.gap = isMobile ? 20 : 40;
      state.current.viewWidth = isMobile
        ? window.innerWidth
        : window.innerWidth / 2;

      const totalWidth =
        (state.current.cardWidth + state.current.gap) * slidesData.length;

      // Max Scroll = Total content width - Visible area + padding
      state.current.maxScroll =
        totalWidth - state.current.viewWidth + (isMobile ? 60 : 100);
    };

    calculateDimensions();
    window.addEventListener("resize", calculateDimensions);

    // --- 2. ANIMATION LOOP (The Physics Engine) ---
    const update = () => {
      const lerpFactor = state.current.isDragging ? 0.5 : 0.08;
      state.current.current +=
        (state.current.target - state.current.current) * lerpFactor;

      cardsRef.current.forEach((card, index) => {
        if (!card) return;

        const { cardWidth, gap, current } = state.current;

        const itemX = index * (cardWidth + gap) - current;

        let displayX = itemX;
        let rotateZ = 0;
        let scale = 1;
        let zIndex = slidesData.length - index;
        let opacity = 1;

        const threshold = 0;

        if (itemX < threshold) {
          displayX = itemX * 0.2;
          rotateZ = Math.max(itemX * 0.05, -10);
          scale = Math.max(1 + itemX * 0.001, 0.85);
          opacity = Math.max(1 + itemX * 0.003, 0);
        }

        gsap.set(card, {
          x: displayX,
          rotation: rotateZ,
          scale: scale,
          zIndex: zIndex,
          opacity: opacity,
          transformOrigin: "left center",
        });
      });
    };

    gsap.ticker.add(update);

    const handleWheel = (e) => {
      const delta = e.deltaY * 0.8;
      state.current.target += delta;
      clampTarget();
    };

    const handleStart = (clientX) => {
      state.current.isDragging = true;
      state.current.startX = clientX;
      state.current.touchStart = state.current.target;
      if (containerRef.current) containerRef.current.style.cursor = "grabbing";
    };

    const handleMove = (clientX) => {
      if (!state.current.isDragging) return;
      const diff = (state.current.startX - clientX) * 1.5;
      state.current.target = state.current.touchStart + diff;
      clampTarget();
    };

    const handleEnd = () => {
      state.current.isDragging = false;
      if (containerRef.current) containerRef.current.style.cursor = "grab";
    };

    const onMouseDown = (e) => handleStart(e.clientX);
    const onMouseMove = (e) => handleMove(e.clientX);
    const onMouseUp = () => handleEnd();

    const onTouchStart = (e) => handleStart(e.touches[0].clientX);
    const onTouchMove = (e) => handleMove(e.touches[0].clientX);
    const onTouchEnd = () => handleEnd();

    const clampTarget = () => {
      const max = state.current.maxScroll;
      if (state.current.target < 0) state.current.target = 0;
      if (state.current.target > max) state.current.target = max;
    };

    window.addEventListener("resize", calculateDimensions);
    window.addEventListener("wheel", handleWheel);
    window.addEventListener("mousedown", onMouseDown);
    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseup", onMouseUp);
    window.addEventListener("touchstart", onTouchStart);
    window.addEventListener("touchmove", onTouchMove);
    window.addEventListener("touchend", onTouchEnd);

    return () => {
      gsap.ticker.remove(update);
      window.removeEventListener("resize", calculateDimensions);
      window.removeEventListener("wheel", handleWheel);
      window.removeEventListener("mousedown", onMouseDown);
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseup", onMouseUp);
      window.removeEventListener("touchstart", onTouchStart);
      window.removeEventListener("touchmove", onTouchMove);
      window.removeEventListener("touchend", onTouchEnd);
    };
  }, [slidesData]);

  return (
    <main className="flex flex-col md:flex-row h-screen w-full bg-white text-black font-sans overflow-hidden">
      <div className="w-full h-[35%] md:w-1/2 md:h-full flex flex-col justify-center px-6 md:px-24 z-20 bg-white relative ">
        <h1 className="text-5xl md:text-8xl font-bold uppercase tracking-tighter mb-4 md:mb-8 leading-[0.85]">
          Star
          <br />
          Inspired
        </h1>
        <div className="w-12 md:w-16 h-1 md:h-2 bg-black mb-4 md:mb-8"></div>
        <p className="text-sm md:text-xl text-gray-600 max-w-md leading-relaxed">
          A collection of wisdom from great minds to fuel your daily motivation.
          <span className="hidden md:inline"> Drag or scroll to explore.</span>
          <span className="md:hidden"> Swipe to explore.</span>
        </p>
      </div>

      <div
        ref={containerRef}
        className="w-full h-[65%] md:w-1/2 md:h-full relative cursor-grab active:cursor-grabbing  overflow-hidden"
      >
        <div className="absolute top-1/2 -translate-y-1/2 left-4 md:left-20 w-full h-[60vh] md:h-[500px] perspective-[1000px]">
          {slidesData.map((slide, index) => (
            <div
              key={index}
              ref={(el) => (cardsRef.current[index] = el)}
              className="absolute top-0 left-0  border-black/5 w-[85vw] h-[55vh] md:w-[400px] md:h-[500px] rounded-[20px] md:rounded-[30px] p-6 md:p-10 flex flex-col justify-between select-none shadow-xl border  will-change-transform"
              style={{
                backgroundColor: slide.color,
                color: slide.textColor,
              }}
            >
              <div className="text-base md:text-lg font-medium opacity-80">
                0{index + 1}
              </div>

              <p className="text-2xl md:text-4xl font-bold leading-tight tracking-tight">
                {slide.text}
              </p>

              <div className="flex items-center gap-3 md:gap-4">
                <div className="w-8 h-8 md:w-10 md:h-10 rounded-full  flex items-center justify-center font-bold text-xs md:text-base">
                  {slide.author[1].toUpperCase()}
                </div>
                <div className="text-xs md:text-sm font-semibold opacity-70">
                  {slide.author}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </main>
  );
}

