"use client";

import React, { useEffect, useRef } from "react";
import gsap from "gsap";

export interface SlideItem {
  text: string;
  author: string;
  color: string;
  textColor: string;
}

interface AuraStackProps {
  slides: SlideItem[];
}

interface SliderState {
  target: number;
  current: number;
  isDragging: boolean;
  startX: number;
  touchStart: number;
  maxScroll: number;
  cardWidth: number;
  gap: number;
  viewWidth: number;
}

export const AuraStackCards: React.FC<AuraStackProps> = ({ slides }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const cardsRef = useRef<(HTMLDivElement | null)[]>([]);

  const state = useRef<SliderState>({
    target: 0,
    current: 0,
    isDragging: false,
    startX: 0,
    touchStart: 0,
    maxScroll: 0,
    cardWidth: 400,
    gap: 40,
    viewWidth: 0,
  });

  useEffect(() => {
    const calculateDimensions = () => {
      const isMobile = window.innerWidth < 768;
      const s = state.current;

      s.cardWidth = isMobile ? window.innerWidth * 0.85 : 400;
      s.gap = isMobile ? 20 : 40;
      s.viewWidth = isMobile ? window.innerWidth : window.innerWidth / 2;

      const totalWidth = (s.cardWidth + s.gap) * slides.length;
      s.maxScroll = totalWidth - s.viewWidth + (isMobile ? 60 : 100);
    };

    const update = () => {
      const s = state.current;
      const lerpFactor = s.isDragging ? 0.5 : 0.08;
      s.current += (s.target - s.current) * lerpFactor;

      cardsRef.current.forEach((card, index) => {
        if (!card) return;

        const itemX = index * (s.cardWidth + s.gap) - s.current;
        let displayX = itemX;
        let rotateZ = 0;
        let scale = 1;
        let zIndex = slides.length - index;
        let opacity = 1;

        // The "Stack" Physics Logic
        if (itemX < 0) {
          displayX = itemX * 0.2;
          rotateZ = Math.max(itemX * 0.05, -10);
          scale = Math.max(1 + itemX * 0.001, 0.85);
          opacity = Math.max(1 + itemX * 0.003, 0);
        }

        gsap.set(card, {
          x: displayX,
          rotation: rotateZ,
          scale: scale,
          zIndex: zIndex,
          opacity: opacity,
          transformOrigin: "left center",
        });
      });
    };

    calculateDimensions();
    gsap.ticker.add(update);

    const clampTarget = () => {
      state.current.target = Math.max(0, Math.min(state.current.target, state.current.maxScroll));
    };

    const handleWheel = (e: WheelEvent) => {
      state.current.target += e.deltaY * 0.8;
      clampTarget();
    };

    const handleStart = (clientX: number) => {
      state.current.isDragging = true;
      state.current.startX = clientX;
      state.current.touchStart = state.current.target;
      if (containerRef.current) containerRef.current.style.cursor = "grabbing";
    };

    const handleMove = (clientX: number) => {
      if (!state.current.isDragging) return;
      const diff = (state.current.startX - clientX) * 1.5;
      state.current.target = state.current.touchStart + diff;
      clampTarget();
    };

    const handleEnd = () => {
      state.current.isDragging = false;
      if (containerRef.current) containerRef.current.style.cursor = "grab";
    };

    // Event Bindings
    const onMouseDown = (e: MouseEvent) => handleStart(e.clientX);
    const onMouseMove = (e: MouseEvent) => handleMove(e.clientX);
    const onTouchStart = (e: TouchEvent) => handleStart(e.touches[0].clientX);
    const onTouchMove = (e: TouchEvent) => handleMove(e.touches[0].clientX);

    window.addEventListener("resize", calculateDimensions);
    window.addEventListener("wheel", handleWheel);
    window.addEventListener("mousedown", onMouseDown);
    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseup", handleEnd);
    window.addEventListener("touchstart", onTouchStart);
    window.addEventListener("touchmove", onTouchMove);
    window.addEventListener("touchend", handleEnd);

    return () => {
      gsap.ticker.remove(update);
      window.removeEventListener("resize", calculateDimensions);
      window.removeEventListener("wheel", handleWheel);
      window.removeEventListener("mousedown", onMouseDown);
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseup", handleEnd);
      window.removeEventListener("touchstart", onTouchStart);
      window.removeEventListener("touchmove", onTouchMove);
      window.removeEventListener("touchend", handleEnd);
    };
  }, [slides.length]);

  return (
    <main className="flex flex-col md:flex-row h-screen w-full bg-white text-black font-sans overflow-hidden">
      <div className="w-full h-[35%] md:w-1/2 md:h-full flex flex-col justify-center px-6 md:px-24 z-20 bg-white relative ">
        <h1 className="text-5xl md:text-8xl font-bold uppercase tracking-tighter mb-4 md:mb-8 leading-[0.85]">
          Aura<br />Stack
        </h1>
        <div className="w-12 md:w-16 h-1 md:h-2 bg-black mb-4 md:mb-8"></div>
        <p className="text-sm md:text-xl text-gray-600 max-w-md leading-relaxed">
          Interactive kinetic scrolling with deep stack physics.
          <span className="hidden md:inline"> Drag or scroll to explore.</span>
        </p>
      </div>

      <div ref={containerRef} className="w-full h-[65%] md:w-1/2 md:h-full relative cursor-grab active:cursor-grabbing overflow-hidden">
        <div className="absolute top-1/2 -translate-y-1/2 left-4 md:left-20 w-full h-[60vh] md:h-[500px]">
          {slides.map((slide, index) => (
            <div
              key={index}
              ref={(el) => { cardsRef.current[index] = el; }}
              className="absolute top-0 left-0 border-black/5 w-[85vw] h-[55vh] md:w-[400px] md:h-[500px] rounded-[20px] md:rounded-[30px] p-6 md:p-10 flex flex-col justify-between select-none shadow-xl border will-change-transform"
              style={{ backgroundColor: slide.color, color: slide.textColor }}
            >
              <div className="text-base md:text-lg font-medium opacity-80">0{index + 1}</div>
              <p className="text-2xl md:text-4xl font-bold leading-tight tracking-tight">{slide.text}</p>
              <div className="flex items-center gap-3 md:gap-4">
                <div className="w-8 h-8 md:w-10 md:h-10 rounded-full flex items-center justify-center font-bold text-xs md:text-base bg-black/10">
                  {slide.author[1]?.toUpperCase()}
                </div>
                <div className="text-xs md:text-sm font-semibold opacity-70">{slide.author}</div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </main>
  );
};

